+                }
+                Files.createDirectories(folder);
+            } else if (!Files.isDirectory(folder)) {
+                throw new StoreInitializationFailedException("Violation store path is not a directory: " + storeFolder.getAbsolutePath());
+            }
+
+            Path index = folder.resolve(STORED_RULES_FILE_NAME);
+            if (existsWithoutFollowingLinks(index)) {
+                if (!Files.isRegularFile(index, LinkOption.NOFOLLOW_LINKS) || !isDirectlyInFolder(index, folder)) {
+                    throw new StoreInitializationFailedException(
+                            "The violation store index must be a regular file directly in the store folder: " + index);
+                }
+            } else if (!storeCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+            return index.toFile();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
