+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeContext) {
+            return storeContext.properties.containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storeContext) {
+            String description = normalize(rule.getDescription());
+            String existingName = storeContext.properties.getProperty(description);
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingName == null) {
+                    return;
+                }
+                forgetRule(description, existingName);
+                return;
+            }
+            if (violations.isEmpty() && existingName == null) {
+                return;
+            }
+
+            String name = existingName != null ? existingName : nameProvider.nameFor(rule.getDescription(), true);
+            validateNameForSave(name, existingName);
+            FileWriteTransaction write = writeViolations(name, violations);
+
+            if (existingName == null) {
+                Properties oldProperties = copyOf(storeContext.properties);
+                storeContext.properties.setProperty(description, normalize(name));
+                try {
+                    storeContext.sync();
+                } catch (RuntimeException e) {
+                    storeContext.properties = oldProperties;
+                    write.rollback();
+                    try {
+                        storeContext.sync();
+                    } catch (RuntimeException ignored) {
+                        // Preserve the original failure; the atomic index replacement normally makes this unnecessary.
+                    }
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private void forgetRule(String description, String name) {
+        IntegrityEntry entry = new IntegrityEntry(description, name);
+        entry.inspectPath();
+        if (isSharedWithAnother(description, name, entry)) {
+            Properties oldProperties = copyOf(storeContext.properties);
+            storeContext.properties.remove(description);
+            try {
+                storeContext.sync();
+            } catch (RuntimeException e) {
+                storeContext.properties = oldProperties;
+                throw e;
+            }
+            return;
+        }
+
+        FileRemovalTransaction removal = prepareRemoval(entry);
+        Properties oldProperties = copyOf(storeContext.properties);
+        storeContext.properties.remove(description);
+        try {
+            storeContext.sync();
+            removal.commit();
+        } catch (RuntimeException e) {
+            storeContext.properties = oldProperties;
+            try {
+                storeContext.sync();
+            } catch (RuntimeException ignored) {
+                // The original exception is more useful to the caller.
+            }
+            removal.rollback();
+            throw e;
+        }
+    }
+
+    private boolean isSharedWithAnother(String description, String name, IntegrityEntry entry) {
+        for (String otherDescription : storeContext.properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = storeContext.properties.getProperty(otherDescription);
+            if (name.equals(otherName)) {
+                return true;
+            }
+            if (entry.validFile && otherName != null) {
+                IntegrityEntry other = new IntegrityEntry(otherDescription, otherName);
+                other.inspectPath();
+                if (other.validFile && sameFile(entry.realPath, other.realPath)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private FileRemovalTransaction prepareRemoval(IntegrityEntry entry) {
+        Path path = entry.lexicalPath;
+        if (path == null) {
+            throw new StoreUpdateFailedException("The stored rule file name is not a valid path: " + entry.recordedName);
+        }
+        try {
+            if (!existsWithoutFollowingLinks(path)) {
+                return new FileRemovalTransaction();
+            }
+            if (Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreUpdateFailedException("Cannot delete stored rule file because it is a directory: " + path);
+            }
+
+            FileRemovalTransaction result = new FileRemovalTransaction();
+            if (Files.isSymbolicLink(path)) {
+                if (entry.validFile) {
+                    result.moveToBackup(entry.realPath);
+                }
+                result.moveToBackup(path);
+            } else {
+                result.moveToBackup(path);
+            }
+            return result;
+        } catch (StoreUpdateFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeContext) {
+            String ruleDetailsFileName = storeContext.properties.getProperty(normalize(rule.getDescription()));
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private FileWriteTransaction writeViolations(String fileName, List<String> violations) {
+        Path target = safePath(fileName);
+        try {
+            Path actualTarget = target;
+            byte[] oldContents = null;
+            boolean existed = existsWithoutFollowingLinks(target);
+            if (existed) {
+                if (Files.isSymbolicLink(target)) {
+                    if (!Files.isRegularFile(target)) {
+                        throw new StoreUpdateFailedException("Stored rule file is not a regular file: " + target);
+                    }
+                    actualTarget = target.toRealPath();
+                } else if (!Files.isRegularFile(target, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreUpdateFailedException("Stored rule file is not a regular file: " + target);
+                }
+                if (!isDirectlyInFolder(actualTarget, storeFolder.toPath())) {
+                    throw new StoreUpdateFailedException("Stored rule file escapes the store folder: " + target);
+                }
+                oldContents = Files.readAllBytes(actualTarget);
+            }
+
+            StringBuilder builder = new StringBuilder();
+            for (String violation : violations) {
+                builder.append(escape(violation)).append('\n');
+            }
+            Path temporary = Files.createTempFile(storeFolder.toPath(), ".violation-", ".tmp");
+            try {
+                Files.write(temporary, builder.toString().getBytes(UTF_8));
+                moveReplacing(temporary, actualTarget);
+            } finally {
+                Files.deleteIfExists(temporary);
+            }
+            return new FileWriteTransaction(actualTarget, existed, oldContents);
+        } catch (StoreUpdateFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void validateNameForSave(String name, String existingName) {
+        if (name == null || name.isEmpty()) {
+            throw new StoreUpdateFailedException("The RuleViolationFileNameStrategy did not provide a file name");
+        }
+        Path path = safePath(name);
+        if (STORED_RULES_FILE_NAME.equals(name)) {
+            throw new StoreUpdateFailedException("A rule violation file cannot be named " + STORED_RULES_FILE_NAME);
+        }
+        try {
+            if (existsWithoutFollowingLinks(path)) {
+                if (existingName == null) {
+                    throw new StoreUpdateFailedException("Refusing to overwrite a file not recorded by the rule: " + path);
+                }
+                if (Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreUpdateFailedException("Stored rule file is not a regular file: " + path);
+                }
+                if (Files.isSymbolicLink(path) && !Files.isRegularFile(path)) {
+                    throw new StoreUpdateFailedException("Stored rule file is not a regular file: " + path);
+                }
+                Path actual = Files.isSymbolicLink(path) ? path.toRealPath() : path;
+                if (!isDirectlyInFolder(actual, storeFolder.toPath())) {
+                    throw new StoreUpdateFailedException("Stored rule file escapes the store folder: " + path);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private Path safePath(String name) {
+        try {
+            Path namePath = Paths.get(name);
+            if (namePath.isAbsolute() || namePath.getNameCount() != 1 || namePath.getParent() != null ||
+                    ".".equals(name) || "..".equals(name) || name.indexOf('/') >= 0 || name.indexOf('\\') >= 0) {
+                throw new StoreUpdateFailedException("Rule violation file name does not name a direct file in the store folder: " + name);
+            }
+            Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+            Path result = folder.resolve(namePath).normalize();
+            if (!folder.equals(result.getParent())) {
+                throw new StoreUpdateFailedException("Rule violation file name escapes the store folder: " + name);
+            }
+            return result;
+        } catch (InvalidPathException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private List<String> readLines(String fileName) {
+        String violationsText = readStoreFile(fileName);
+        List<String> result = new ArrayList<>();
+        Matcher matcher = UNESCAPED_LINE_BREAK.matcher(violationsText);
+        int start = 0;
+        while (matcher.find()) {
+            String line = violationsText.substring(start, matcher.start());
+            if (line.endsWith("\r") && !isEscapedAtEnd(line)) {
+                line = line.substring(0, line.length() - 1);
+            }
+            if (!line.isEmpty()) {
+                result.add(unescape(line));
+            }
+            start = matcher.end();
+        }
+        String last = violationsText.substring(start);
+        if (!last.isEmpty()) {
+            result.add(unescape(last));
+        }
+        return result;
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return new String(Files.readAllBytes(storeFolder.toPath().resolve(fileName)), UTF_8);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
+    }
+
+    private IntegrityReport inspect(Properties properties) {
+        List<IntegrityEntry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            IntegrityEntry entry = new IntegrityEntry(description, properties.getProperty(description));
+            entry.inspectPath();
+            if (nameProvider.canDerive) {
+                entry.derivedName = nameProvider.nameFor(description, true);
+                entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            }
+            entries.add(entry);
+        }
+
+        markShared(entries);
+        Map<String, List<IntegrityEntry>> byDerivedName = new HashMap<>();
+        for (IntegrityEntry entry : entries) {
+            if (entry.derivedName != null) {
+                byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (List<IntegrityEntry> colliding : byDerivedName.values()) {
+            if (colliding.size() > 1) {
+                for (IntegrityEntry entry : colliding) {
+                    entry.colliding = true;
+                }
+            }
+        }
+        for (IntegrityEntry entry : entries) {
+            if (entry.misplaced) {
+                entry.occupied = isOccupied(entry, entries);
+            }
+        }
+
+        List<Path> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private void markShared(List<IntegrityEntry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            IntegrityEntry left = entries.get(i);
+            for (int j = i + 1; j < entries.size(); j++) {
+                IntegrityEntry right = entries.get(j);
+                if (left.recordedName.equals(right.recordedName) ||
+                        (left.validFile && right.validFile && sameFile(left.realPath, right.realPath))) {
+                    left.shared = true;
+                    right.shared = true;
+                }
+            }
+        }
